INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('tpl AI semi time', 'kz', 'Әр 2 дайындамаға шамамен 1-2 минут; шығыны «ЖИ шығыны» бетінде (semi_ai).'), ('tpl AI semi time', 'ru', 'Примерно 1-2 минуты на 2 заготовки; расходы на странице «Расходы ИИ» (semi_ai).'), ('tpl AI semi time', 'en', 'About 1-2 minutes per 2 semis; cost on the AI cost page (semi_ai).'), ('tpl AI semi time', 'uz', 'Har 2 ta uchun taxminan 1-2 daqiqa; xarajat «SI xarajati» sahifasida (semi_ai).'), ('tpl AI semi time', 'ky', 'Ар 2 даярдамага болжол менен 1-2 мүнөт; чыгым «ЖИ чыгымы» бетинде (semi_ai).');
