INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('tpl No empty semis', 'kz', 'Рецепті жоқ, шаблоны бар дайындама жоқ. Жаңасын «Дайындама қосу» арқылы шаблоннан не ЖИ-мен қосыңыз.'), ('tpl No empty semis', 'ru', 'Нет заготовок без рецепта, для которых есть шаблон. Новую добавьте через «Добавить заготовку» из шаблона или с ИИ.'), ('tpl No empty semis', 'en', 'No semis without a recipe that have a template. Add a new one via «Add semi» from a template or with AI.'), ('tpl No empty semis', 'uz', 'Retseptsiz, shabloni bor yarim tayyor yo‘q. Yangisini shablondan yoki SI bilan qo‘shing.'), ('tpl No empty semis', 'ky', 'Рецепти жок, шаблону бар даярдама жок. Жаңысын шаблондон же ЖИ менен кошуңуз.');
INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('tpl Pick semis', 'kz', 'Дайындама таңдаңыз'), ('tpl Pick semis', 'ru', 'Выберите заготовки'), ('tpl Pick semis', 'en', 'Pick semis'), ('tpl Pick semis', 'uz', 'Yarim tayyorlarni tanlang'), ('tpl Pick semis', 'ky', 'Даярдама тандаңыз');
INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('tpl Semi all text', 'kz', 'Рецепті жоқ дайындамаларға шаблоннан құрам жазылады: жоқ шикізат пен ішкі дайындамалар ашылады, бағасы базадан не ЖИ-ден толады.'), ('tpl Semi all text', 'ru', 'Заготовкам без рецепта запишется состав из шаблона: недостающее сырьё и вложенные заготовки создадутся, цены возьмутся из базы или от ИИ.'), ('tpl Semi all text', 'en', 'Semis without a recipe get a composition from the template: missing raw items and nested semis are created, prices come from the database or AI.'), ('tpl Semi all text', 'uz', 'Retseptsiz yarim tayyorlarga shablondan tarkib yoziladi: yetishmagan xomashyo va ichki yarim tayyorlar yaratiladi, narxlar bazadan yoki SI dan.'), ('tpl Semi all text', 'ky', 'Рецепти жок даярдамаларга шаблондон курам жазылат: жетишпеген чийки зат жана ички даярдамалар ачылат, баасы базадан же ЖИден.');
INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('tpl Semi miss note', 'kz', 'Компаниялардағы дайындамалар мен шаблондардағы дайындама құрамдар, шаблоны жоқтары. ЖИ орташа рецепт құрады (ішкі дайындамаларымен бірге, толық тізбек), жоғарыда тексеріп бекітесіз.'), ('tpl Semi miss note', 'ru', 'Заготовки компаний и компоненты-заготовки в шаблонах без своего шаблона. ИИ составит средний рецепт (с вложенными заготовками), вы проверите и утвердите выше.'), ('tpl Semi miss note', 'en', 'Company semis and semi-like template items without a template. AI builds an average recipe (with nested semis); you review and approve above.'), ('tpl Semi miss note', 'uz', 'Kompaniyalardagi va shablonlardagi shabloni yo‘q yarim tayyorlar. SI o‘rtacha retsept tuzadi, siz yuqorida tekshirib tasdiqlaysiz.'), ('tpl Semi miss note', 'ky', 'Компаниялардагы жана шаблондордогу шаблону жок даярдамалар. ЖИ орточо рецепт түзөт, жогоруда текшерип бекитесиз.');
INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('tpl Semi note', 'kz', 'Дайындама шаблоны: құрамның мөлшері бүкіл шығымға (кг құрам граммен, л — мл-мен). Тағам шаблонындағы аттас құрам осыған байланады: компания тағамға шаблон қойғанда дайындама өз рецептімен ашылады (шикізат → дайындама → тағам).'), ('tpl Semi note', 'ru', 'Шаблон заготовки: количества на весь выход (кг в граммах, л в мл). Одноимённый компонент в шаблонах блюд связывается с ним: при применении шаблона заготовка создаётся со своим рецептом (сырьё → заготовка → блюдо).'), ('tpl Semi note', 'en', 'Semi template: amounts are for the whole yield (kg in grams, l in ml). A dish template item with the same name links to it: applying the dish template creates the semi with its own recipe (raw → semi → dish).'), ('tpl Semi note', 'uz', 'Yarim tayyor shabloni: miqdor butun chiqishga (kg grammda, l ml da). Taom shablonidagi shu nomli komponent unga bog‘lanadi (xomashyo → yarim tayyor → taom).'), ('tpl Semi note', 'ky', 'Даярдама шаблону: өлчөм бүт чыгымга (кг граммда, л млде). Тамак шаблонундагы аттас курам ага байланат (чийки зат → даярдама → тамак).');
